examples:
```cpp
std::vector<int> values(10);
auto generator{std::bind(distribution, engine)};
std::generate(std::begin(values), std::end(values), generator);
for (auto i : values) {
    std::cout << i << std::endl;
}
```

生成器也可以作为函数参数传递：```cpp
void fillVector(std::vector<int>& values,
                const std::function<int()>& generator) {
    std::generate(std::begin(values), std::end(values), generator);
}
```

若不想使用 `std::function`，也可以使用函数模板：```cpp
template<typename T>
void fillVector(std::vector<int>& values, const T& generator) {
    std::generate(std::begin(values), std::end(values), generator);
}
```
